    b_tuples = data['option_b_ratings'].apply(tuple)

    mask = (a_tuples == (1, 1, 1, 0, 0, 0, 0)) & (b_tuples == (0, 0, 0, 1, 1, 1, 1))

    subset = data[mask]
    if len(subset) == 0:
        return 0.5

    return float(subset['response'].mean())

